## Why This Is Asked

This question introduces offline-first syncing with conflict resolution, a common beginner E2E scenario that tests practical skills with service workers, IndexedDB, and test orchestration across browser contexts.

## Key Concepts

- Offline-first architecture and PWA fundamentals
- Service workers for caching and network interception
- IndexedDB for local persistent storage
- Test isolation using multiple browser contexts
- Conflict resolution strategies (last-write-wins, merge, CRDT)
- Idempotent sync operations and data seeding

## Code Example

```javascript
const { test, expect } = require('@playwright/test');

test.describe('Note-taking PWA E2E', () => {
  let contextA, contextB, pageA, pageB;

  test.beforeEach(async ({ browser }) => {
    // Create two isolated browser contexts to simulate two devices
    contextA = await browser.newContext();
    contextB = await browser.newContext();
    pageA = await contextA.newPage();
    pageB = await contextB.newPage();

    // Seed initial notes into IndexedDB for both contexts
    await seedInitialNotes(pageA);
    await seedInitialNotes(pageB);
  });

  test('syncs notes without duplicates after going offline/online', async () => {
    // Step 1: Simulate offline mode on Device A
    await pageA.route('**/*', route => route.abort('offline'));

    // Step 2: Create and edit a note while offline
    const noteId = await createNoteOffline(pageA, 'Original Title', 'Original Content');
    await editNoteOffline(pageA, noteId, 'Updated Title', 'Updated Content');

    // Step 3: Bring Device B online and make a conflicting edit
    await pageB.goto('/');
    await pageB.waitForSelector('[data-testid="note-list"]');
    await editNote(pageB, noteId, 'Conflicting Title', 'Conflicting Content');

    // Step 4: Restore connectivity on Device A to trigger sync
    await pageA.unrouteAll();

    // Step 5: Verify sync completes within 10 seconds
    await expect(pageA.locator('[data-testid="sync-status"]')).toHaveText('Synced', { timeout: 10000 });

    // Step 6: Assert no duplicates and correct timestamps
    const notes = await getAllNotes(pageA);
    const duplicateNotes = notes.filter(n => n.title === 'Updated Title');

    expect(duplicateNotes).toHaveLength(1);
    expect(notes[0].updatedAt).toBeGreaterThan(notes[0].createdAt);
  });

  async function seedInitialNotes(page) {
    await page.evaluate(() => {
      const request = indexedDB.open('NotesDB', 1);
      request.onupgradeneeded = (event) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains('notes')) {
          db.createObjectStore('notes', { keyPath: 'id' });
        }
      };
      request.onsuccess = (event) => {
        const db = event.target.result;
        const tx = db.transaction('notes', 'readwrite');
        const store = tx.objectStore('notes');
        store.put({ id: 'note-1', title: 'Welcome', content: 'Welcome to the app!', createdAt: Date.now(), updatedAt: Date.now() });
      };
    });
  }

  async function createNoteOffline(page, title, content) {
    return await page.evaluate(([t, c]) => {
      return new Promise((resolve) => {
        const request = indexedDB.open('NotesDB', 1);
        request.onsuccess = (event) => {
          const db = event.target.result;
          const tx = db.transaction('notes', 'readwrite');
          const store = tx.objectStore('notes');
          const id = 'note-' + Date.now();
          store.put({ id, title: t, content: c, createdAt: Date.now(), updatedAt: Date.now() });
          tx.oncomplete = () => resolve(id);
        };
      });
    }, [title, content]);
  }

  async function editNote(page, id, title, content) {
    await page.click(`[data-testid="note-${id}"]`);
    await page.fill('[data-testid="title-input"]', title);
    await page.fill('[data-testid="content-input"]', content);
    await page.click('[data-testid="save-button"]');
  }

  async function getAllNotes(page) {
    return await page.evaluate(() => {
      return new Promise((resolve) => {
        const request = indexedDB.open('NotesDB', 1);
        request.onsuccess = (event) => {
          const db = event.target.result;
          const tx = db.transaction('notes', 'readonly');
          const store = tx.objectStore('notes');
          const getAll = store.getAll();
          getAll.onsuccess = () => resolve(getAll.result);
        };
      });
    });
  }
});
```

## How to Verify End-to-End Success

1. **Tooling**: Playwright with isolated browser contexts provides proper data isolation while simulating real multi-device scenarios
2. **Data Isolation**: Each browser context has its own IndexedDB instance, ensuring tests don't interfere with each other
3. **Success Criteria**: 
   - Notes sync within 10 seconds of connectivity restored
   - No duplicate entries exist after sync
   - Timestamps are preserved and accurate
   - Conflict resolution produces consistent results

## Why This Is Asked
Tests that exercise keyboard accessibility demonstrate familiarity with a11y concepts and deterministic testing approaches for beginners.

## Key Concepts
- Keyboard navigation and focus management
- ARIA roles and attributes (role=dialog, aria-label, aria-live)
- Test determinism with seeded localStorage and deterministic delays

## Code Example

```javascript
// Example test outline in Cypress
describe('Keyboard accessibility for notes', () => {
  it('navigates via Tab, opens modal, saves, edits, deletes, and persists', () => {
    // seed
    window.localStorage.setItem('notes', JSON.stringify([
      { id: 1, title: 'Note 1', body: 'Body 1' },
      { id: 2, title: 'Note 2', body: 'Body 2' }
    ]));

    cy.visit('/');

    // Tab through list and verify focus
    cy.get('[data-testid="note-item"]').first().focus();
    cy.focused().should('have.attr', 'role', 'listitem');

    // Open create modal with keyboard
    cy.get('[data-testid="create-button"]').focus().type('{enter}');
    cy.get('[role="dialog"]').should('be.visible');

    // Create note
    cy.get('[data-testid="note-title"]').type('New Note');
    cy.get('[data-testid="note-body"]').type('New Body');
    cy.get('[data-testid="save-button"]').click();

    // Edit existing note
    cy.get('[data-testid="note-item"]').first().focus().type('{enter}');
    cy.get('[data-testid="note-title"]').clear().type('Edited Title');
    cy.get('[data-testid="save-button"]').click();

    // Delete note
    cy.get('[data-testid="note-item"]').first().focus();
    cy.get('[data-testid="delete-button"]').click();

    // Verify persistence after reload
    cy.reload();
    cy.window().then(win => {
      const notes = JSON.parse(win.localStorage.getItem('notes'));
      expect(notes).to.have.length(2);
    });
  });
});
```

## Why This Is Asked

Tests critical authorization paths, data-loss prevention, and audit integrity in multi-tenant setups, plus resilience to flaky services and retention policies.

## Key Concepts

- RBAC and DLP enforcement across tenants
- Tamper-evident audit logs (sequencing, signatures/HMAC)
- End-to-end data export redaction
- Seeds and mocks for deterministic, isolated tests
- Flaky service handling and time-based retention checks

## Code Example

```javascript
// Pseudo end-to-end test sketch (Playwright/Cypress-agnostic)
async function testRBACAndDLP() {
  const t = seedTenant('tenantA');
  const uOwner = seedUser(t, 'owner');
  const uEditor = seedUser(t, 'editor');
  const uAuditor = seedUser(t, 'auditor');
  const admin = seedUser(t, 'admin');

  // Owner creates a share with PII
  await login(uOwner);
  await createShare({ tenant: t.id, data: 'PII' });

  // Editor attempts restricted action
  await login(uEditor);
  assertAccessDenied(editShare(t.id));

  // Auditor reads audit trail
  await login(uAuditor);
  assertAuditIncludes(t.id, 'READ', uAuditor.id);

  // Admin exports with redaction
  await login(admin);
  const exportPayload = await exportData(t.id);
  assertRedacts(exportPayload, ['PII']);
  // Verify tamper-evident log
  assertTamperEvidence(t.id);
}
```

## Why This Is Asked
This question evaluates the candidate's understanding of end-to-end testing for real-time, distributed systems with regional routing, data consistency, and feature flag safety.

## Key Concepts
- End-to-end testing of event-driven pipelines, cross-region latency, and eventual consistency
- Test data isolation and deterministic environments via mocks and seed data
- Idempotency, replay safety, and rollback semantics for feature flags
- Instrumentation hooks to seed Kafka, mock external feeds, and reset Redis

## Code Example
```javascript
// Playwright test scaffold for the trading alert pipeline
const { test, expect } = require('@playwright/test');

test.describe('Multi-Region Alerting System', () => {
  let kafkaSeeder;
  let redisClient;
  let mockExternalFeed;

  test.beforeEach(async () => {
    // Seed isolated test data per region
    await redisClient.flushdb();
    await kafkaSeeder.seedEvents([
      { region: 'us-east', symbol: 'AAPL', threshold: 150 },
      { region: 'eu-west', symbol: 'BMW', threshold: 85 },
    ]);
    mockExternalFeed.setDeterministicResponse({ AAPL: { price: 152 }, BMW: { price: 87 } });
  });

  test('alerts propagate to correct regional dashboards', async ({ page }) => {
    await page.goto('https://dashboard.trading.example.com');
    await expect(page.locator('.alert').first()).toBeVisible({ timeout: 5000 });

    // Verify cross-region routing
    const alerts = await page.locator('.alert').all();
    expect(alerts).toHaveLength(2);
  });

  test('feature flag rollback triggers correctly', async ({ page }) => {
    await page.goto('https://dashboard.trading.example.com');
    await page.evaluate(() => window.triggerRollback());
    await expect(page.locator('.rollback-success')).toBeVisible();
  });
});
```

